  "Sans minimum": "Nessun minimo",
  "Cadences du PGN": "PGN Controlli temporali",
  "Sans maximum": "Nessun massimo",
  "Aucune coche = toutes les cadences, y compris les inconnues.": "Nessuna selezione = tutti i controlli temporali, compresi gli sconosciuti.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo proviene dal PGN e deve essere all'interno della gamma per entrambi i giocatori. i giochi di scacchi senza Elo sono esclusi quando è impostato un limite. I controlli temporali PGN mancanti o non riconosciuti sono \"Inconosciuti\". Questi giochi di scacchi sono esclusi quando vengono selezionati i controlli temporali, a meno che non sia selezionato \"Inconosciuto\".",
  ": indique un nombre valide pour la borne Elo.": ": inserire un numero valido per la fascia Elo.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": inserire un numero intero Elo da 0 a 4000, oppure lasciare il punto connesso in bianco.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": il minimo Elo non può superare il massimo Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "Crea un database e importa PGN giochi di scacchi nella biblioteca.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess master non dispone di filtri Elo o di controllo del tempo. Per filtrare una collezione principale, scegliere un database importato come Mega Database.",
  "Source principale": "Fonte principale",
  "Mes bases PGN": "Le mie banche dati PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "Sono contate solo le mosse di scacchi di linea principale. Le variazioni di analisi non gonfiano le statistiche.",
  "Référence dans chaque ligne": "Referenza in ogni riga",
  "Comparer avec": "Comparare con",
  "Mes bases de référence": "Le mie banche dati di riferimento",
  "Aucune référence": "Nessun riferimento",
  "Ces filtres sont indépendants de la base principale. Le pourcentage indique la fréquence du coup à cette position dans la référence choisie.": "Questi filtri sono indipendenti dal database principale. La percentuale mostra la frequenza di movimento degli scacchi in questa posizione del riferimento scelto.",
  "Probabilité de rencontre": "Probabilità di incontro",
  "Afficher la probabilité de la ligne": "Mostra la probabilità della linea",
  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "Scegli il tuo lato direttamente nell'esploratore. Solo le risposte dell'avversario contano, le tue mosse di scacchi sono presunte. Questa stima segue la variazione visualizzata e i filtri di database selezionati. Per un PGN partendo da un diagramma, è condizionato da tale posizione di partenza.",
  "Mode d’analyse": "Modalità di analisi",
  "Rapide (~250 ms par coup)": "Rapido (~ 250 ms per mossa di scacchi)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "Una maggiore profondità migliora l'analisi e richiede più tempo. Da 8 a 30, con un limite di 10 secondi per mossa di scacchi. Se l'obiettivo non è raggiunto, ≈ segna il risultato; pendolo per vedere la sua profondità effettiva.",
