  ". Chaque probabilité suppose son départ déjà atteint ; elles ne s’additionnent pas entre ces départs.": ". Ogni probabilità presuppone che la sua posizione di partenza sia stata raggiunta; le probabilità non possono essere sommate tra le posizioni di partenza.",
  "Ce répertoire commence sur un diagramme : les probabilités supposent cette position déjà atteinte.": "Questo repertorio iniziale parte da un diagramma: le probabilità presuppongono che questa posizione sia già stata raggiunta.",
