  "Sélectionne une activité pour explorer ton temps.": "Seleziona un’attività per esaminare il tempo dedicato.",
  "Aucune durée mesurée sur cette période. Les nouvelles activités apparaîtront ici automatiquement.": "Nessuna durata misurata in questo periodo. Le nuove attività appariranno qui automaticamente.",
  "{count} activité(s) ont une durée inconnue. Elles ne sont pas comptées comme zéro.": "Attività con durata sconosciuta: {count}. Non vengono conteggiate come zero.",
  "{count} durée(s) inconnue(s)": "Durate sconosciute: {count}",
  "Le temps au fil des jours": "Il tempo dedicato giorno per giorno",
  "Chaque couleur représente une activité. Survole une barre pour voir sa durée.": "Ogni colore rappresenta un’attività. Passa il puntatore su una barra per vederne la durata.",
  "Temps enregistré par période et par activité": "Tempo registrato per periodo e attività",
  "Répartition du temps": "Distribuzione del tempo",
  "Répartition du temps par activité": "Distribuzione del tempo per attività",
  "au total": "in totale",
  "La régularité en un regard": "La costanza a colpo d’occhio",
  "Une case par jour. Plus la couleur est intense, plus tu as consacré de temps.": "Una casella per giorno. Più il colore è intenso, maggiore è il tempo dedicato.",
  "Calendrier du temps consacré": "Calendario del tempo dedicato",
  "Ton rythme dans la semaine": "Il tuo ritmo settimanale",
  "Temps moyen pour chaque jour de la semaine, jours sans activité inclus.": "Tempo medio per ogni giorno della settimana, compresi i giorni senza attività.",
  "Voir les données": "Visualizza i dati",
  "Durées enregistrées pour les activités sélectionnées": "Durate registrate per le attività selezionate",
  "Stockfish sert à l’analyse et au jeu classique; Maia reproduit un jeu humain. Les bases de référence et de puzzles restent facultatives.": "Stockfish serve per l’analisi e il gioco classico; Maia riproduce il gioco umano. I database di riferimento e di problemi restano facoltativi.",
  "Quand ChessGym est ouvert, les versions compatibles des moteurs et les bases installées compatibles sont vérifiées puis actualisées. Les éditions Lumbra se téléchargent séparément sur leur site. Les téléchargements peuvent être volumineux.": "Quando ChessGym è in esecuzione, le versioni compatibili dei motori e dei database installati vengono verificate e aggiornate. Le edizioni Lumbra si scaricano separatamente dal loro sito. I download possono essere di grandi dimensioni.",
  "Licence : {license}": "Licenza: {license}",
  "Conditions de licence": "Condizioni di licenza",
  "Par Michael Jansen. Usage non commercial avec attribution; une licence distincte est nécessaire pour un usage commercial.": "Di Michael Jansen. Uso non commerciale con attribuzione; per l’uso commerciale occorre una licenza separata.",
  "Télécharge cette édition sur le site Lumbra, accepte sa licence, puis indique le fichier .7z ou .pgn présent sur le PC ou serveur de ChessGym.": "Scarica questa edizione dal sito Lumbra, accetta la licenza e indica il file .7z o .pgn presente sul PC o sul server che esegue ChessGym.",
  "Télécharger sur Lumbra": "Scarica da Lumbra",
  "Chemin du fichier téléchargé sur le serveur": "Percorso del file scaricato sul server",
  "Utiliser comme référence de maîtres": "Usa come database di riferimento dei maestri",
  "Importer la base téléchargée": "Importa il database scaricato",
  "Les nouvelles éditions Lumbra se téléchargent sur leur site; les mises à jour automatiques ne les remplacent pas.": "Le nuove edizioni Lumbra si scaricano dal loro sito; gli aggiornamenti automatici non le sostituiscono.",
  "Taille de l’archive : environ {size} Mo": "Dimensione dell’archivio: circa {size} MB",
  "Indique le chemin du fichier Lumbra téléchargé.": "Indica il percorso del file Lumbra scaricato.",
  "Lumbra OTB Elite — maîtres 2400+": "Lumbra OTB Elite — maestri 2400+",
  "Lumbra Gigabase OTB — complète": "Lumbra Gigabase OTB — completa",
  "Parties sur échiquier entre deux joueurs classés au moins 2400 Elo. Télécharge l’archive officielle, puis importe-la ici.": "Partite a tavolino tra due giocatori con almeno 2400 Elo ciascuno. Scarica l’archivio ufficiale e importalo qui.",
  "Collection complète des parties sur échiquier. L’import et l’indexation peuvent prendre plusieurs heures et beaucoup d’espace disque.": "Raccolta completa delle partite a tavolino. L’importazione e l’indicizzazione possono richiedere diverse ore e molto spazio su disco.",
  "Gratuit avec attribution pour un usage non commercial. Une licence distincte est nécessaire pour un usage commercial.": "Gratuito per uso non commerciale con attribuzione. Per l’uso commerciale occorre una licenza separata.",
  "Vérification et copie de l’archive Lumbra": "Verifica e copia dell’archivio Lumbra",
  "Lecture de l’archive Lumbra": "Lettura dell’archivio Lumbra",
  "Décompression du PGN Lumbra": "Estrazione del PGN Lumbra",
  "Ajout de la base Lumbra à la bibliothèque": "Aggiunta del database Lumbra alla biblioteca",
  "Préparation de la base Lumbra": "Preparazione del database Lumbra",
  "Cette base Lumbra est déjà installée": "Questo database Lumbra è già installato",
  "Base Lumbra disponible": "Database Lumbra pronto",
  "7-Zip n’est pas détecté sur le serveur. Installe-le pour importer une archive .7z, ou fournis un PGN déjà extrait.": "7-Zip non è stato rilevato sul server. Installalo per importare un archivio .7z oppure fornisci un PGN già estratto.",
  "Installe 7-Zip sur le serveur, ou décompresse l’archive et importe directement son fichier PGN.": "Installa 7-Zip sul server oppure estrai l’archivio e importa direttamente il suo file PGN.",
  "Bonus dans 1 coup : +{seconds} s": "Bonus tra 1 mossa: +{seconds} s",
  "Seule la résolution sans erreur compte pour le classement. La reconstruction est une statistique secondaire, sans effet sur la cote. Une erreur, une révélation ou un abandon avant la fin de la solution peut faire baisser la cote.": "Solo una soluzione senza errori conta per il punteggio. La ricostruzione è una statistica secondaria e non influisce sul punteggio. Un errore, la visualizzazione della soluzione o l’abbandono prima di completarla possono far scendere il punteggio.",
  "Classé : seule la résolution sans erreur compte. La reconstruction ne change pas la cote.": "Con punteggio: conta solo la soluzione senza errori. La ricostruzione non modifica il punteggio.",
  "Solution sans erreur.": "Soluzione senza errori.",
  "Aucun point gagné : une solution complète sans erreur est requise.": "Nessun punto guadagnato: serve una soluzione completa senza errori.",
  "Passer la reconstruction": "Salta la ricostruzione",
  "Position départ": "Posizione di partenza",
  "Position initiale standard": "Posizione iniziale standard",
  "Statistique secondaire : cette étape ne change ni la réussite du puzzle ni la cote.": "Statistica secondaria: questa fase non modifica né l’esito del problema né il punteggio.",
  "Position finale · statistique secondaire": "Posizione finale · statistica secondaria",
  "Non effectuée": "Non effettuata",
