  "Seules les bases cochées apparaissent dans le menu Deviner le coup.": "Solo i database selezionati appaiono nel menu Indovina la mossa.",
  "Retour aux bases": "Torna ai database",
  "{count} partie": "{count} partita",
  "Et {count} autres…": "E altre {count}…",
  "Les parties sélectionnées seront supprimées de cette base de référence. Le fichier PGN original est conservé. Cette action ne peut pas être annulée.": "Le partite selezionate verranno eliminate da questo database di riferimento. Il file PGN originale viene conservato. Questa azione non può essere annullata.",
  "Les parties seront copiées dans la base choisie, puis supprimées de cette base de référence. Le fichier PGN original est conservé.": "Le partite verranno copiate nel database scelto, poi eliminate da questo database di riferimento. Il file PGN originale viene conservato.",
  "Une copie indépendante sera créée avec tous les coups, variantes et commentaires.": "Verrà creata una copia indipendente con tutte le mosse, le varianti e i commenti.",
  "{count} partie supprimée.": "{count} partita eliminata.",
  "{count} parties supprimées.": "{count} partite eliminate.",
  "{count} partie dupliquée.": "{count} partita duplicata.",
  "{count} parties dupliquées.": "{count} partite duplicate.",
  "{count} partie déplacée.": "{count} partita spostata.",
  "{count} parties déplacées.": "{count} partite spostate.",
  "Sélectionne des parties pour les dupliquer, les déplacer ou les supprimer. Pour les annoter ou les réviser, duplique-les dans une base personnelle. L’explorer et la recherche de positions utilisent la ligne principale des parties de référence.": "Seleziona le partite da duplicare, spostare o eliminare. Per annotarle o ripassarle, duplicale in un database personale. L’esploratore e la ricerca di posizioni usano la linea principale delle partite di riferimento.",
  "Reprends la partie pour continuer.": "Riprendi la partita per continuare.",
  "Reconstruction non effectuée": "Ricostruzione non effettuata",
  "Tout réviser": "Ripassa tutto",
  "Tout apprendre": "Impara tutto",
  "Un lancement attend une confirmation. Réessaie le même choix pour retrouver tes cartes.": "L’avvio è in attesa di conferma. Ripeti la stessa scelta per ritrovare le tue schede.",
  "Réviser / Apprendre": "Ripassa / Impara",
  "Cartes à travailler": "Schede da studiare",
  "Les erreurs personnelles et puzzles échoués proviennent des exercices déjà présents dans tes bases actives. Les révisions dues passent avant les nouvelles cartes.": "Gli errori personali e i problemi non risolti provengono dagli esercizi già presenti nei tuoi database attivi. I ripassi da fare hanno la precedenza sulle nuove schede.",
  "La sélection ne correspond pas au bloc du programme.": "La selezione non corrisponde al blocco del programma.",
