  "Les révisions dues passent avant les nouvelles cartes. Le volume dépend de l’objectif du bloc.": "I ripassi da fare hanno la precedenza sulle nuove schede. Il carico dipende dall’obiettivo del blocco.",
  "Les révisions dues passent avant les nouvelles cartes.": "I ripassi da fare hanno la precedenza sulle nuove schede.",
