  "Ces objectifs proposent une pause sans modifier les échéances. Tu peux les adapter au lancement.": "Questi obiettivi suggeriscono una pausa senza modificare le scadenze. Puoi adattarli all’avvio.",
  "Choisis les bases à mettre à jour avec les valeurs globales Manqué, Difficile, Bien et Facile. Les échéances et l’historique restent conservés.": "Scegli i database da aggiornare con i valori globali Di nuovo, Difficile, Bene e Facile. Le scadenze e la cronologia vengono conservate.",
